// === Tab: mySketch ===
var noiseScale = 500; 
var total = 0; 
var colors = [
    {r: 35, g: 80, b: 172}, // 蓝色
    {r: 13, g: 14, b: 16},  // 黑色
    {r: 253, g: 171, b: 25} // 黄色
];

let starImg, townImg, riverImg, fieldImg; // 声明图像变量
let images = []; // 存储所有图像的数组
let currentImageIndex = 0; // 当前显示的图片索引
let sound; // 声明音频变量

class OrbitingBall {
    constructor(center, radius, speed, color) {
        this.angle = random(TWO_PI); // 随机初始角度
        this.radius = radius; // 半径
        this.speed = speed; // 旋转速度
        this.color = color; // 颜色
    }

    move(center) {
        this.angle += this.speed; // 更新角度
        this.position = createVector(center.x + cos(this.angle) * this.radius, center.y + sin(this.angle) * this.radius);
    }
}

class Particle {
    constructor(position, color, speed) {
        this.position = position; // 粒子的位置
        this.color = color;       // 粒子的颜色
        this.speed = speed;       // 粒子的速度
        this.size = random(5, 15); // 粒子的大小随机在 5 到 15 之间
        this.alpha = 0;           // 初始透明度为 0，用于新粒子的渐显效果
        this.direction = createVector(0, 0); // 方向向量，初始为 (0, 0)
        this.lifespan = Math.floor(random(100, 255)); // 粒子的生命值，随机生成
    }

    move() {
        this.alpha++;

        if (this.lifespan > 0) {
            this.lifespan--;
        }

        this.angle = noise(this.position.x / noiseScale, this.position.y / noiseScale) * TWO_PI;
        this.direction.x = -cos(this.angle);
        this.direction.y = sin(this.angle);

        let mousePos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
        let distance = this.position.dist(mousePos);

        if (distance < 75) {
            let awayDirection = p5.Vector.sub(this.position, mousePos);
            awayDirection.setMag(this.speed);
            this.position.add(awayDirection);
        } else {
            this.position.add(p5.Vector.mult(this.direction, this.speed));
        }
    }
}

var particles = []; // 存储粒子的数组
var orbitingBalls = []; // 存储旋转的小球

function preload() {
    starImg = loadImage('https://openprocessing.org/sketch/2409878/files/moon.png');  // 加载 star 图片
    townImg = loadImage('https://openprocessing.org/sketch/2409878/files/town.png');  // 加载 town 图片
    riverImg = loadImage('https://openprocessing.org/sketch/2409878/files/river.png'); // 加载 river 图片
    fieldImg = loadImage('https://openprocessing.org/sketch/2409878/files/field.png');  // 加载 field 图片
    sound = loadSound('https://openprocessing.org/sketch/2409878/files/810431149.mp3'); // 加载音频文件

    // 将所有图片添加到数组中
    images = [townImg, riverImg, fieldImg];
}

function setup() {
    noStroke(); 
    createCanvas(1000, 750); 
    total = (windowWidth / 40) * (windowHeight / 40); // 减慢粒子生成速度
    sound.play(); // 程序开始时播放音频

    for (var i = 0; i < total; i++) {
        let colorIndex;
        const rand = random(); 
        if (rand < 0.6) { 
            colorIndex = 0; // 蓝色，增加生成比例
        } else if (rand < 0.85) { 
            colorIndex = 1; // 黑色，减少生成比例
        } else {
            colorIndex = 2; // 黄色，减少生成比例
        }
        particles.push(new Particle(createVector(random(width), random(height)), colors[colorIndex], random(0.5, 1)));
    }
}

function draw() {
    fill(18, 63, 119, 10);
    rect(0, 0, width, height); 

    // 使用图像绘制星星图像
    imageMode(CENTER);
    image(starImg, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 200, 200);

    // 绘制旋转的小球
    for (let ball of orbitingBalls) {
        ball.move(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
        fill(ball.color.r, ball.color.g, ball.color.b);
        ellipse(ball.position.x, ball.position.y, random(10, 15));
    }

    // 绘制粒子
    for (var i = 0; i < particles.length; i++) {
        const {position, size, color, alpha} = particles[i];
        const {r, g, b} = color; 
        const {x, y} = position; 
        fill(r, g, b, alpha);
        ellipse(x, y, size);
        particles[i].move();

        if (particles[i].lifespan === 0 || x < 0 || x > width || y > height || y < 0) {
            particles.splice(i, 1);
            particles.push(new Particle(createVector(random(width), random(height)), colors[Math.floor(random(3))], random(0.5, 1)));
        }
    }

    // 直接将背景图像按画布大小拉伸
    imageMode(CORNER);
    image(images[currentImageIndex], 0, 0, width, height); 
}

// 当鼠标点击时切换图片
function mousePressed() {
    currentImageIndex = (currentImageIndex + 1) % images.length; // 每次点击切换到下一张图片
}

